resolved AS (
  SELECT "app_menus_ids".actual_id AS "menu_id",
    "auth_roles_ids".actual_id AS "role_id"
  FROM source_rows
  LEFT JOIN pg_temp.vibehr_reference_seed_ids AS "app_menus_ids"
    ON "app_menus_ids".source_table = 'app_menus'
   AND "app_menus_ids".source_id = source_rows."menu_id"
  LEFT JOIN pg_temp.vibehr_reference_seed_ids AS "auth_roles_ids"
    ON "auth_roles_ids".source_table = 'auth_roles'
   AND "auth_roles_ids".source_id = source_rows."role_id"
)
INSERT INTO public."app_menu_roles" ("menu_id", "role_id")
SELECT source."menu_id", source."role_id"
FROM resolved AS source
WHERE NOT EXISTS (
  SELECT 1
  FROM public."app_menu_roles" AS target
  WHERE target."menu_id" IS NOT DISTINCT FROM source."menu_id"
  AND target."role_id" IS NOT DISTINCT FROM source."role_id"
);



-- Python welfare overrides replace role links only for the four canonical welfare menus.
WITH desired (menu_source_id, role_source_id) AS (
  VALUES
    (88, 1),
    (88, 2),
    (88, 3),
    (89, 1),
    (89, 2),
    (89, 3),
    (114, 1),
    (114, 2),
    (114, 3),
    (115, 1),
    (115, 2),
    (115, 4)
),
resolved AS (
  SELECT menu_ids.actual_id AS menu_id, role_ids.actual_id AS role_id
  FROM desired
  JOIN pg_temp.vibehr_reference_seed_ids AS menu_ids
    ON menu_ids.source_table = 'app_menus' AND menu_ids.source_id = desired.menu_source_id
  JOIN pg_temp.vibehr_reference_seed_ids AS role_ids
    ON role_ids.source_table = 'auth_roles' AND role_ids.source_id = desired.role_source_id
)
DELETE FROM public."app_menu_roles" AS link
USING public."app_menus" AS menu
WHERE link."menu_id" = menu."id"
  AND menu."code" IN ('wel', 'wel.requests', 'wel.my-requests', 'wel.benefit-types')
  AND NOT EXISTS (
    SELECT 1 FROM resolved
    WHERE resolved.menu_id = link."menu_id"
      AND resolved.role_id = link."role_id"
  );

