resolved AS (
  SELECT source_rows."id" AS "id",
    "app_menus_ids".actual_id AS "menu_id",
    source_rows."action_code" AS "action_code",
    source_rows."enabled_default" AS "enabled_default",
    source_rows."created_at" AS "created_at",
    source_rows."updated_at" AS "updated_at"
  FROM source_rows
  LEFT JOIN pg_temp.vibehr_reference_seed_ids AS "app_menus_ids"
    ON "app_menus_ids".source_table = 'app_menus'
   AND "app_menus_ids".source_id = source_rows."menu_id"
)
INSERT INTO pg_temp.vibehr_reference_seed_ids (source_table, source_id, actual_id)
SELECT 'app_menu_actions', source."id", target."id"
FROM resolved AS source
JOIN public."app_menu_actions" AS target
  ON target."menu_id" IS NOT DISTINCT FROM source."menu_id"
  AND target."action_code" IS NOT DISTINCT FROM source."action_code"
ON CONFLICT (source_table, source_id) DO UPDATE
SET actual_id = EXCLUDED.actual_id;

WITH source_rows ("id", "key", "category", "value_type", "value_text", "description", "is_active", "updated_by", "updated_at") AS (
  VALUES
    (CAST(1 AS integer), CAST('auth.session.access_ttl_min' AS character varying), CAST('auth' AS character varying), CAST('int' AS character varying), CAST('120' AS character varying), CAST('Access JWT 만료시간(분)' AS character varying), CAST(true AS boolean), CAST(NULL AS integer), CAST('2026-01-01 00:00:00' AS timestamp without time zone)),
    (CAST(2 AS integer), CAST('auth.session.refresh_threshold_min' AS character varying), CAST('auth' AS character varying), CAST('int' AS character varying), CAST('60' AS character varying), CAST('갱신 임계치(분)' AS character varying), CAST(true AS boolean), CAST(NULL AS integer), CAST('2026-01-01 00:00:00' AS timestamp without time zone)),
    (CAST(3 AS integer), CAST('auth.session.remember_enabled' AS character varying), CAST('auth' AS character varying), CAST('bool' AS character varying), CAST('true' AS character varying), CAST('Remember me 허용 여부' AS character varying), CAST(true AS boolean), CAST(NULL AS integer), CAST('2026-01-01 00:00:00' AS timestamp without time zone)),
    (CAST(4 AS integer), CAST('auth.session.remember_ttl_min' AS character varying), CAST('auth' AS character varying), CAST('int' AS character varying), CAST('43200' AS character varying), CAST('Remember me 쿠키 만료(분)' AS character varying), CAST(true AS boolean), CAST(NULL AS integer), CAST('2026-01-01 00:00:00' AS timestamp without time zone)),
    (CAST(5 AS integer), CAST('auth.session.show_countdown' AS character varying), CAST('auth' AS character varying), CAST('bool' AS character varying), CAST('true' AS character varying), CAST('상단 세션 카운트다운 표시 여부' AS character varying), CAST(true AS boolean), CAST(NULL AS integer), CAST('2026-01-01 00:00:00' AS timestamp without time zone))
),
resolved AS (
  SELECT source_rows."id" AS "id",
    source_rows."key" AS "key",
    source_rows."category" AS "category",
    source_rows."value_type" AS "value_type",
    source_rows."value_text" AS "value_text",
    source_rows."description" AS "description",
    source_rows."is_active" AS "is_active",
    source_rows."updated_by" AS "updated_by",
    source_rows."updated_at" AS "updated_at"
  FROM source_rows
)
INSERT INTO public."app_system_settings" ("key", "category", "value_type", "value_text", "description", "is_active", "updated_by", "updated_at")
SELECT source."key", source."category", source."value_type", source."value_text", source."description", source."is_active", source."updated_by", source."updated_at"
FROM resolved AS source
WHERE NOT EXISTS (
  SELECT 1
  FROM public."app_system_settings" AS target
  WHERE target."key" IS NOT DISTINCT FROM source."key"
);

