INSERT INTO pg_temp.vibehr_reference_seed_ids (source_table, source_id, actual_id)
SELECT 'wel_benefit_types', source."id", target."id"
FROM resolved AS source
JOIN public."wel_benefit_types" AS target
  ON target."code" IS NOT DISTINCT FROM source."code"
ON CONFLICT (source_table, source_id) DO UPDATE
SET actual_id = EXCLUDED.actual_id;

-- Reference rows never reuse source primary keys; advance only sequences owned by an id column.
DO $$
DECLARE
    target_table text;
    sequence_name text;
    max_id bigint;
    target_tables text[] := ARRAY['PAP_APPRAISAL_MASTERS', 'PAP_FINAL_RESULTS', 'app_code_groups', 'app_codes', 'app_menu_actions', 'app_menu_roles', 'app_menus', 'app_system_settings', 'auth_roles', 'gl_accounts', 'hr_retire_checklist_items', 'hri_approval_actor_rules', 'hri_approval_line_steps', 'hri_approval_line_templates', 'hri_form_type_approval_maps', 'hri_form_type_policies', 'hri_form_types', 'org_corporations', 'org_departments', 'pay_allowance_deductions', 'pay_gl_mappings', 'pay_income_tax_brackets', 'pay_item_groups', 'pay_payroll_codes', 'pay_severance_item_rules', 'pay_tax_rates', 'tim_attendance_codes', 'tim_department_schedule_assignments', 'tim_holidays', 'tim_schedule_pattern_days', 'tim_schedule_patterns', 'tim_work_schedule_codes', 'wel_benefit_types'];
BEGIN
    FOREACH target_table IN ARRAY target_tables LOOP
        IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = target_table AND column_name = 'id') THEN
            SELECT pg_get_serial_sequence(format('public.%I', target_table), 'id') INTO sequence_name;
            IF sequence_name IS NOT NULL THEN
                EXECUTE format('SELECT max(id) FROM public.%I', target_table) INTO max_id;
                PERFORM setval(sequence_name, GREATEST(COALESCE(max_id, 1), 1), true);
            END IF;
        END IF;
    END LOOP;
END $$;
